// shouldRetryRideHistory is like shouldRetry, but only recreates the
// ride_history table.
func (d *database) shouldRetryRideHistory(err error) bool {
	if mysqlErr, ok := err.(*mysql.MySQLError); ok && mysqlErr.Number == 1146 {
		return d.createRideHistoryTable() == nil
	}
	return false
}

const rideHistoryColumns = "id, pickup_location, dropoff_location, request_time, driver_plate, fare"

func (d *database) ListRideHistory(ctx context.Context) (*RideHistory, error) {
	d.logger.For(ctx).Info("Loading ride history")

	_, span := d.tracer.Start(ctx, "SQL SELECT", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		semconv.PeerServiceKey.String("mysql"),
		attribute.
			Key("sql.query").
			String("SELECT "+rideHistoryColumns+" FROM ride_history"),
	)
	defer span.End()

	query := "SELECT " + rideHistoryColumns + " FROM ride_history ORDER BY request_time DESC, id DESC"
	rows, err := d.db.Query(query)
	if err != nil {
		if !d.shouldRetryRideHistory(err) {
			return nil, err
		}
		rows, err = d.db.Query(query)
		if err != nil {
			return nil, err
		}
	}
	defer rows.Close()
	history := &RideHistory{Rides: []RideHistoryEntry{}}
	for rows.Next() {
		var e RideHistoryEntry
		if err := rows.Scan(&e.ID, &e.PickupLocation, &e.DropoffLocation, &e.RequestTime,
			&e.DriverPlate, &e.Fare); err != nil {
			return nil, err
		}
		history.Rides = append(history.Rides, e)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	history.Total = len(history.Rides)
	return history, nil
}

func (d *database) CreateRideHistory(ctx context.Context, e *RideHistoryEntry) (int64, error) {
	query := "INSERT INTO ride_history SET pickup_location = ?, dropoff_location = ?, " +
		"request_time = ?, driver_plate = ?, fare = ?"
	args := []interface{}{e.PickupLocation, e.DropoffLocation, e.RequestTime, e.DriverPlate, e.Fare}
	res, err := d.db.Exec(query, args...)
	if err != nil {
		if !d.shouldRetryRideHistory(err) {
			return 0, err
		}
		res, err = d.db.Exec(query, args...)
		if err != nil {
			return 0, err
		}
	}
	return res.LastInsertId()
}

// UpdateRideHistory sets the driver plate and fare of an existing entry and
// returns the updated entry.
func (d *database) UpdateRideHistory(ctx context.Context, u *RideHistoryUpdate) (*RideHistoryEntry, error) {
	query := "UPDATE ride_history SET driver_plate = ?, fare = ? WHERE id = ?"
	res, err := d.db.Exec(query, u.DriverPlate, u.Fare, u.ID)
	if err != nil {
		if !d.shouldRetryRideHistory(err) {
			return nil, err
		}
		res, err = d.db.Exec(query, u.DriverPlate, u.Fare, u.ID)
		if err != nil {
			return nil, err
		}
	}
	// MySQL reports 0 affected rows when the values are unchanged, so look the
	// entry up to tell "unchanged" from "not found".
	if _, err := res.RowsAffected(); err != nil {
		return nil, err
	}
	var e RideHistoryEntry
	row := d.db.QueryRow("SELECT "+rideHistoryColumns+" FROM ride_history WHERE id = ?", u.ID)
	if err := row.Scan(&e.ID, &e.PickupLocation, &e.DropoffLocation, &e.RequestTime,
		&e.DriverPlate, &e.Fare); err != nil {
		return nil, err
	}
	return &e, nil
}
