  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  const reqs = [];
  page.on('response', r => { if (r.url().includes('ride-history') || r.url().includes('dispatch')) reqs.push(r.request().method() + ' ' + r.url().split('8080')[1] + ' ' + r.status()); });
