  await page.getByRole('button', { name: 'Request Ride' }).click();
  await page.waitForTimeout(9000);
  const text = await page.innerText('body');
  await page.screenshot({ path: '/tmp/hotrod-run/phase1.png', fullPage: true });
  return { errors, reqs, text: text.slice(text.indexOf('Request Ride')) };
}

