package driver

import (
	"testing"
	"time"
)

func TestCalculateFare(t *testing.T) {
	tests := []struct {
		name string
		eta  time.Duration
		want float64
	}{
		{"zero ETA gets the minimum fare", 0, 3.50},
		{"negative ETA gets the minimum fare", -time.Minute, 3.50},
		{"below the minimum", time.Minute, 3.50},
		{"exactly the minimum", 2*time.Minute + 20*time.Second, 3.50},
		{"whole minutes", 10 * time.Minute, 15.00},
		{"fractional minutes", 5*time.Minute + 56*time.Second, 8.90},
		{"rounded to cents", 3*time.Minute + 7*time.Second, 4.70},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := calculateFare(tt.eta); got != tt.want {
				t.Errorf("calculateFare(%v) = %v, want %v", tt.eta, got, tt.want)
			}
		})
	}
}
EOF
